// Package gamedata embeds the game rules that Godot exports: progression_rules.json (progresion.md
// §13.4, plataforma.md §4.4). It is generated by ProgressionRulesExport.build() and written by
// tools/progression/export_rules.gd; tests/test_progression_rules_export.gd checks that the
// repository's file matches the code's rules. It is not edited by hand here.
//
// Two sections are from plataforma.md: protocol_version ([Rules.ProtocolVersion], the default
// ELDMARK_MIN_PROTOCOL in dev and test) and names ([Names], which internal/names reads). The others
// (races, appearance, templates, items...) are read by progress.LoadRules (progresion.md P7) from
// [Raw].
package gamedata

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"sync"
)

//go:embed progression_rules.json
var raw []byte

// Raw returns the file as is (progress.LoadRules reads it whole). It must not be modified.
func Raw() []byte { return raw }

// Names is the names section: what NameRules needs to validate and normalize names.
type Names struct {
	MinLength    int               `json:"min_length"`
	MaxLength    int               `json:"max_length"`
	UpperLetters string            `json:"upper_letters"` // same order as LowerLetters
	LowerLetters string            `json:"lower_letters"`
	Folded       map[string]string `json:"folded"`   // lowercase letter -> the one that counts in the key
	Reserved     []string          `json:"reserved"` // as written in NameRules
}

// Rules are the plataforma.md sections. The rest of the file is not looked at here.
type Rules struct {
	ProtocolVersion int   `json:"protocol_version"`
	Names           Names `json:"names"`
}

// Parse reads the plataforma.md sections of a progression_rules.json and checks that they make
// sense. The keys of other sections do not count (they are from progresion.md).
func Parse(b []byte) (*Rules, error) {
	var top map[string]json.RawMessage
	if err := json.Unmarshal(b, &top); err != nil {
		return nil, fmt.Errorf("gamedata: progression_rules.json no es JSON válido: %w", err)
	}
	r := &Rules{}
	for key, dst := range map[string]any{"protocol_version": &r.ProtocolVersion, "names": &r.Names} {
		v, ok := top[key]
		if !ok {
			return nil, fmt.Errorf("gamedata: falta la sección %q", key)
		}
		if err := json.Unmarshal(v, dst); err != nil {
			return nil, fmt.Errorf("gamedata: sección %q: %w", key, err)
		}
	}
	if err := r.check(); err != nil {
		return nil, err
	}
	return r, nil
}

func (r *Rules) check() error {
	n := r.Names
	switch {
	case r.ProtocolVersion < 1:
		return errors.New("gamedata: protocol_version tiene que ser mayor que 0")
	case n.MinLength < 1 || n.MaxLength < n.MinLength:
		return errors.New("gamedata: names: longitudes que no tienen sentido")
	case n.UpperLetters == "" || len([]rune(n.UpperLetters)) != len([]rune(n.LowerLetters)):
		return errors.New("gamedata: names: upper_letters y lower_letters tienen que tener las mismas letras")
	}
	for from, to := range n.Folded {
		if len([]rune(from)) != 1 || len([]rune(to)) != 1 {
			return fmt.Errorf("gamedata: names: folded %q → %q no es de una letra a una letra", from, to)
		}
	}
	return nil
}

var (
	once     sync.Once
	embedded *Rules
	errEmbed error
)

// Load returns the rules embedded in the binary. A broken file is a repository error (the Godot
// test and this package's test catch it beforehand): serve does not start.
func Load() (*Rules, error) {
	once.Do(func() { embedded, errEmbed = Parse(raw) })
	return embedded, errEmbed
}

// MustLoad is [Load] for tests and default values: it panics if the embedded file is not valid.
func MustLoad() *Rules {
	r, err := Load()
	if err != nil {
		panic(err)
	}
	return r
}
